parameters.jsCode:
// Normalize each Gmail message into the fields the classifier needs,
// and flag obvious bulk/automated mail so we never spend an AI call on it.
return $input.all().map(item => {
  const m = item.json;
  const headers = m.headers || {};
  // Header values arrive like "list-unsubscribe: <mailto:...>"; compare lowercased.
  const h = key => String(headers[key] || '').toLowerCase();

  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddr = String(sender.address || '').toLowerCase();
  const fromName = sender.name || '';
  const subject = m.subject || '';
  // Plain-text body, whitespace collapsed, capped to keep the prompt cheap.
  const body = String(m.text || '').replace(/\s+/g, ' ').trim().slice(0, 4000);

  const automatedSender = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?@|newsletter|bounce)/i.test(fromAddr);
  const autoSubmitted = h('auto-submitted');
  const bulkHeaders =
    Boolean(headers['list-unsubscribe']) ||              // mailing lists and marketing
    /(bulk|list|junk)/.test(h('precedence')) ||
    (autoSubmitted !== '' && !/(^|:\s*)no\s*$/.test(autoSubmitted)); // auto-generated mail
  // Only answer first contact, so a reply to our auto-reply never loops.
  const isReply = /^\s*(re|fwd?|aw)\s*:/i.test(subject);
  const isSelf = Boolean(m.myAddress) && fromAddr === String(m.myAddress).toLowerCase();

  let skipReason = '';
  if (isSelf) skipReason = 'sent by me';
  else if (automatedSender) skipReason = 'automated sender';
  else if (bulkHeaders) skipReason = 'bulk or mailing-list headers';
  else if (isReply) skipReason = 'existing conversation';

  return {
    json: {
      messageId: m.id,
      threadId: m.threadId,
      fromAddr,
      fromName,
      firstName: fromName.split(/\s+/)[0] || '',
      subject,
      body,
      skipReason,
    },
  };
});

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "opportunity",
        "marketing",
        "spam",
        "personal",
        "other"
      ]
    },
    "is_spam": {
      "type": "boolean"
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1, how sure you are of the category"
    },
    "topic": {
      "type": "string"
    },
    "reason": {
      "type": "string",
      "description": "One sentence explaining the decision"
    }
  },
  "required": [
    "category",
    "is_spam",
    "confidence",
    "topic",
    "reason"
  ]
}
